package group.zn.zero.npc; import java.util.Objects; public record NpcSnapshot(NpcId npcId,String templateId,String zoneId,String sceneId,String ownerActorId,NpcLifecycleState lifecycle,BehaviorState behavior,long version,long spawnedAt,long lastTickAt,String traceId){public NpcSnapshot{Objects.requireNonNull(npcId);Objects.requireNonNull(templateId);Objects.requireNonNull(lifecycle);Objects.requireNonNull(behavior);if(version<0)throw new IllegalArgumentException("negative version");}}
